def parse_date_candidate(text: str):
    """Return (year, month, day) or None from OCR text, choosing plausible."""
    cands = []
    for line in text.split("\n"):
        s = line.strip()
        if not s:
            continue
        # 4-digit year form
        for m in DATE_PATTERNS[0].finditer(s):
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            if 1 <= d <= 31 and 1 <= mo <= 12 and 2000 <= y <= 2099:
