                mo = MONTHS[mon_txt]
                y = int(m.group(3))
                if y < 100:
                    y = 2000 + y if y < 80 else 1900 + y
                if 1 <= d <= 31 and 2000 <= y <= 2099:
                    cands.append((y, mo, d, s))
            except Exception:
                pass
    if not cands:
        return None
    # Prefer candidates on a line that mentions DATE/TIME keywords
    def score(c):
        y, mo, d, s = c
        u = s.upper()
        sc = 0
        if "DATE" in u:
            sc += 3
        if re.search(r"\d{1,2}:\d{2}", s):
            sc += 1
        # penalize obviously invalid
        return sc
    cands.sort(key=score, reverse=True)
    y, mo, d, _ = cands[0]
    return f"{y:04d}-{mo:02d}-{d:02d}"


