    for tok in reversed(matches):
        v = to_float(tok)
        if v is not None and min_val <= v <= max_val:
            return v
    # last-resort digit run split
    runs = re.findall(r"\d(?:[\d ]{1,4}\d)?", canon)
    for tok in reversed(runs):
        digits = tok.replace(" ", "")
        if 3 <= len(digits) <= 7:
            try:
                v = float(f"{digits[:-2]}.{digits[-2:]}")
            except ValueError:
                continue
            if min_val <= v <= max_val:
                return v
    return None


