    ["GRANDTOTAL"],
    ["TOTALRM"],
    ["TOTALAMOUNT"],
    ["TOTALDUE", "AMOUNTDUE", "BALANCEDUE",
     "NETTOTAL", "NETTTOTAL", "TOTAL", "AMOUNT"],
