    ac = ImageOps.autocontrast(gray)
    up = ac.resize((ac.width * 2, ac.height * 2), Image.LANCZOS)
    variants = [
        ("raw", img),
        ("gray_ac", ac),
        ("up", up),
        ("up_sharp", up.filter(ImageFilter.SHARPEN)),
    ]
    texts = []
    for name, v in variants:
        for psm in ["--psm 6", "--psm 4", "--psm 11"]:
            try:
                t = pytesseract.image_to_string(v, config=psm)
                texts.append((f"{name}/{psm}", t))
            except Exception:
                pass
    return texts


# ---------- Date extraction ----------

MONTHS = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "SEPT": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

DATE_RE_4Y = re.compile(r"(\d{1,2})[/\-.](\d{1,2})[/\-.](20\d{2})")
DATE_RE_ISO = re.compile(r"(20\d{2})[/\-.](\d{1,2})[/\-.](\d{1,2})")
DATE_RE_2Y = re.compile(r"(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)")
DATE_RE_MMM = re.compile(r"(\d{1,2})[ \-]([A-Za-z]{3,4})[ \-](\d{2,4})")


def parse_dates_from_text(text: str):
    """Yield (year, month, day, score) from OCR text."""
    for line in text.split("\n"):
        s = line.strip()
        if not s:
            continue
        u = s.upper()
        line_score = 0
        if "DATE" in u:
            line_score += 3
        if re.search(r"\d{1,2}:\d{2}", s):
            line_score += 1
        seen_spans = []

        def add(y, mo, d, span):
            if 2000 <= y <= 2099 and 1 <= mo <= 12 and 1 <= d <= 31:
                seen_spans.append((span, (y, mo, d)))

        for m in DATE_RE_4Y.finditer(s):
            add(int(m.group(3)), int(m.group(2)), int(m.group(1)), m.span())
        for m in DATE_RE_ISO.finditer(s):
            add(int(m.group(1)), int(m.group(2)), int(m.group(3)), m.span())
        for m in DATE_RE_2Y.finditer(s):
            y = int(m.group(3))
            y = 2000 + y if y < 80 else 1900 + y
            add(y, int(m.group(2)), int(m.group(1)), m.span())
        for m in DATE_RE_MMM.finditer(s):
            mon_txt = m.group(2).upper()
            if mon_txt not in MONTHS:
                continue
            y = int(m.group(3))
            if y < 100:
                y = 2000 + y if y < 80 else 1900 + y
            add(y, MONTHS[mon_txt], int(m.group(1)), m.span())

        for _, ymd in seen_spans:
            yield (*ymd, line_score)


def extract_date(texts):
    """Vote across all variants; each variant contributes its top candidate."""
    per_variant_top = []
    all_candidates = Counter()
    for _, t in texts:
        best = None  # (score, ymd)
        seen = set()
        for y, mo, d, sc in parse_dates_from_text(t):
            key = (y, mo, d)
            if key in seen:
                continue
            seen.add(key)
            all_candidates[key] += 1
            if best is None or sc > best[0]:
                best = (sc, key)
        if best is not None:
            per_variant_top.append(best[1])
    if not per_variant_top:
        return None
    # Majority vote across variants' top choices
    top_counts = Counter(per_variant_top)
    winner, _ = top_counts.most_common(1)[0]
    # Tie-break using overall frequency
    top = top_counts.most_common()
    if len(top) > 1 and top[0][1] == top[1][1]:
        tied = [k for k, v in top if v == top[0][1]]
        winner = max(tied, key=lambda k: all_candidates[k])
    y, mo, d = winner
    return f"{y:04d}-{mo:02d}-{d:02d}"


# ---------- Total extraction ----------

MONEY_RE = re.compile(r"\d{1,3}(?:[,\. ]\d{3})*[.,:\s]\d{2}(?!\d)")


def canonicalize(line: str) -> str:
    s = re.sub(r"\s+", " ", line)
    s = re.sub(r"(?<=\d)[:;|](?=\d)", ".", s)
    s = re.sub(r"(?<=\d)[Oo](?=\d)", "0", s)
    return s


def to_float(tok: str):
    tok = tok.strip()
    m = re.search(r"([.,:\s])(\d{2})$", tok)
    if not m:
        return None
