    frac_part = m.group(2)
    if not int_part.isdigit():
        return None
    try:
        return float(f"{int_part}.{frac_part}")
    except ValueError:
        return None


def extract_money(line: str, min_val=0.01, max_val=1_000_000):
    canon = canonicalize(line)
    matches = MONEY_RE.findall(canon)
    for tok in reversed(matches):
        v = to_float(tok)
        if v is not None and min_val <= v <= max_val:
            return v
    return None


def extract_money_lastresort(line: str, min_val=0.01, max_val=1_000_000):
    """Digit-run fallback: recover values whose decimal was OCR-eaten."""
    canon = canonicalize(line)
    runs = re.findall(r"\d(?:[\d ]{1,4}\d)?", canon)
    for tok in reversed(runs):
        digits = tok.replace(" ", "")
        if 3 <= len(digits) <= 5:
            try:
                v = float(f"{digits[:-2]}.{digits[-2:]}")
            except ValueError:
                continue
            if min_val <= v <= max_val:
                return v
    return None


PAYMENT_TOKENS = ["VISA", "MASTERCARD", "MASTER", "AMEX", "CASH",
                  "DEBIT", "CREDIT", "TENDERED"]


def line_is_payment(raw: str) -> bool:
    n = normalize(raw)
    return any(p in n for p in PAYMENT_TOKENS)


def check_line_for_tier(raw: str, keys):
    """Return (matches_tier, has_valid_position) — line matches tier and is
    not blocked by exclusions."""
    n = normalize(raw)
    key_positions = [n.find(k) for k in keys if k in n]
    if not key_positions:
        return False
    key_pos = min(key_positions)
    for e in HARD_EXCLUSIONS:
        if e in n:
            return False
    for e in SOFT_EXCLUSIONS:
        p = n.find(e)
        if p != -1 and p < key_pos:
            return False
    return True


def find_total_in_text(text: str):
    """Return (tier_idx, value, same_line_bool, source) or None."""
    lines = [ln for ln in text.split("\n")]
    # Determine cutoff at "GST SUMMARY" / "TAX SUMMARY" line - anything after
    # is ignored (those are tax breakdown, not totals).
    cutoff = len(lines)
    for i, ln in enumerate(lines):
        n = normalize(ln)
        if "GSTSUMMARY" in n or "TAXSUMMARY" in n:
            cutoff = i
            break
    active = lines[:cutoff]

    for tier_idx, keys in enumerate(PRIORITY_TIERS):
        same_line_hits = []  # (i, raw, v)
        keyword_only_hits = []  # (i, raw) — no digits on line
        for i, raw in enumerate(active):
            if not check_line_for_tier(raw, keys):
                continue
            v = extract_money(raw)
            if v is not None:
                same_line_hits.append((i, raw, v))
            elif not re.search(r"\d", raw):
                keyword_only_hits.append((i, raw))
        if same_line_hits:
            i, raw, v = same_line_hits[-1]
            return tier_idx, v, True, raw
        # Fallback: next-line for keyword-only lines
        for i, raw in reversed(keyword_only_hits):
            for j in range(i + 1, min(len(active), i + 3)):
                nxt = active[j].strip()
                if not nxt:
                    continue
                if line_is_payment(nxt):
                    break
                v = extract_money(nxt) or extract_money_lastresort(nxt)
                if v is not None:
                    return tier_idx, v, False, f"{raw} || {nxt}"
                break
    return None


def extract_total(texts):
    """Vote across variants; prefer same-line matches at lowest tier."""
    # Collect (tier, value, same_line) per variant
    results = []
    for _, t in texts:
        r = find_total_in_text(t)
        if r is not None:
            tier, val, same, _src = r
            results.append((tier, val, same))
    if not results:
        return None
    # Prefer same-line matches; find lowest tier among them
    same_line = [r for r in results if r[2]]
    pool = same_line if same_line else results
    min_tier = min(r[0] for r in pool)
    pool = [r for r in pool if r[0] == min_tier]
    # Vote on value
    counts = Counter(round(r[1], 2) for r in pool)
    winner, _ = counts.most_common(1)[0]
    return f"{winner:.2f}"


# ---------- Driver ----------

def process_image(path: Path):
    texts = ocr_variants(path)
    return extract_date(texts), extract_total(texts)


def main():
    files = sorted(p for p in IMG_DIR.iterdir()
                   if p.suffix.lower() in {".jpg", ".jpeg", ".png"})
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for p in files:
        date, total = process_image(p)
        print(f"{p.name}: date={date}, total={total}", flush=True)
        ws.append([p.name, date, total])
    wb.save(OUT_FILE)


if __name__ == "__main__":
    main()
