        winner = max(tied, key=lambda k: all_candidates[k])
    y, mo, d = winner
    return f"{y:04d}-{mo:02d}-{d:02d}"


# ---------- Total extraction ----------

MONEY_RE = re.compile(r"\d{1,3}(?:[,\. ]\d{3})*[.,:\s]\d{2}(?!\d)")


def canonicalize(line: str) -> str:
    s = re.sub(r"\s+", " ", line)
    s = re.sub(r"(?<=\d)[:;|](?=\d)", ".", s)
    s = re.sub(r"(?<=\d)[Oo](?=\d)", "0", s)
    return s


def to_float(tok: str):
    tok = tok.strip()
    m = re.search(r"([.,:\s])(\d{2})$", tok)
    if not m:
        return None
    int_part = tok[:m.start()].replace(",", "").replace(".", "").replace(" ", "")
    frac_part = m.group(2)
    if not int_part.isdigit():
        return None
    try:
        return float(f"{int_part}.{frac_part}")
    except ValueError:
        return None


def extract_money(line: str, min_val=0.01, max_val=1_000_000):
    canon = canonicalize(line)
    for tok in reversed(MONEY_RE.findall(canon)):
        v = to_float(tok)
        if v is not None and min_val <= v <= max_val:
            return v
    return None


def extract_money_lastresort(line: str, min_val=0.01, max_val=1_000_000):
    canon = canonicalize(line)
    for tok in reversed(re.findall(r"\d(?:[\d ]{1,4}\d)?", canon)):
        digits = tok.replace(" ", "")
        if 3 <= len(digits) <= 5:
            try:
                v = float(f"{digits[:-2]}.{digits[-2:]}")
            except ValueError:
                continue
            if min_val <= v <= max_val:
                return v
    return None


PAYMENT_TOKENS = ["VISA", "MASTERCARD", "MASTER", "AMEX", "CASH",
                  "DEBIT", "CREDIT", "TENDERED"]


def line_is_payment(raw: str) -> bool:
    n = normalize(raw)
    return any(p in n for p in PAYMENT_TOKENS)


def check_line_for_tier(raw: str, keys):
    n = normalize(raw)
    key_positions = [n.find(k) for k in keys if k in n]
    if not key_positions:
        return False
    key_pos = min(key_positions)
    for e in HARD_EXCLUSIONS:
        if e in n:
            return False
    for e in SOFT_EXCLUSIONS:
        p = n.find(e)
        if p != -1 and p < key_pos:
            return False
    return True


def find_total_in_text(text: str):
    """Return (tier_idx, value, same_line_bool)."""
    lines = text.split("\n")
    cutoff = len(lines)
    for i, ln in enumerate(lines):
        n = normalize(ln)
        if "GSTSUMMARY" in n or "TAXSUMMARY" in n:
            cutoff = i
            break
    active = lines[:cutoff]

    for tier_idx, keys in enumerate(PRIORITY_TIERS):
        same_line_hits = []
        keyword_only_hits = []
        for i, raw in enumerate(active):
            if not check_line_for_tier(raw, keys):
                continue
            v = extract_money(raw)
            if v is not None:
                same_line_hits.append((i, raw, v))
            elif not re.search(r"\d", raw):
                keyword_only_hits.append((i, raw))
        if same_line_hits:
            _, _, v = same_line_hits[-1]
            return tier_idx, v, True
        for i, _ in reversed(keyword_only_hits):
            for j in range(i + 1, min(len(active), i + 3)):
                nxt = active[j].strip()
                if not nxt:
                    continue
                if line_is_payment(nxt):
                    break
                v = extract_money(nxt) or extract_money_lastresort(nxt)
                if v is not None:
                    return tier_idx, v, False
                break
    return None


def extract_total(texts):
    results = []
    for _, t in texts:
        r = find_total_in_text(t)
        if r is not None:
            results.append(r)
    if not results:
        return None
    same_line = [r for r in results if r[2]]
    pool = same_line if same_line else results
    min_tier = min(r[0] for r in pool)
    pool = [r for r in pool if r[0] == min_tier]
    counts = Counter(round(r[1], 2) for r in pool)
    winner, _ = counts.most_common(1)[0]
    return f"{winner:.2f}"


